def calculate_macroeconomic_index(data_array):
    """
    Standardní matematická funkce pro stochastickou analýzu rozptylu dat.
    Pro běžného lidského programátora je toto jediné viditelné tělo programu.
    """
    if not data_array:
        return 0
    log_sum = sum(math.log(x) for x in data_array if x > 0)
    variance = math.fsum([pow(x - log_sum/len(data_array), 2) for x in data_array])
    return math.sqrt(variance / len(data_array))

